mtri_seed$::jsonb as catalog), points as (
  select topic->>'id' as id, topic->>'name' as name, topic->>'short' as short,
    null::text as parent_id, topic->'position' as position, topic->>'color' as color
  from seed cross join lateral jsonb_array_elements(seed.catalog->'topics') as topic
  union all
  select child->>'id', child->>'name', child->>'name',
    topic->>'id', child->'position', topic->>'color'
  from seed cross join lateral jsonb_array_elements(seed.catalog->'topics') as topic
    cross join lateral jsonb_array_elements(topic->'children') as child
)
